// n8n já fragmentou o array do Supabase em N itens (1 por clínica).
const items = $input.all().map(i => i.json).filter(it => it && it.clinic_id && Array.isArray(it.pacientes));
if (items.length === 0) return [{ json: { skip: true } }];
return items.map(item => ({ json: item }));

// Parse output do LLM e emite 1 item por envio.
const clinic = $('Um item por clínica').item.json;
const llm = $input.first().json;
let content = '';
try {
  content = llm?.choices?.[0]?.message?.content || '';
} catch { content = ''; }
let parsed = {};
try { parsed = JSON.parse(content); } catch { parsed = { envios: [] }; }
const envios = Array.isArray(parsed.envios) ? parsed.envios : [];
const byId = new Map((clinic.pacientes || []).map((p) => [String(p.cs_cliente_id), p]));
const out = [];
for (const e of envios) {
  const p = byId.get(String(e.cs_cliente_id));
  if (!p || !p.telefone) continue;
  const msg = String(e.mensagem || '').trim();
  if (!msg) continue;
  out.push({ json: {
    clinic_id: clinic.clinic_id,
    instance_name: clinic.instance_name,
    regra_hash: clinic.regra_hash,
    cs_cliente_id: p.cs_cliente_id,
    telefone: p.telefone,
    mensagem: msg
  }});
}
if (out.length === 0) return [{ json: { skip: true } }];
return out;
